card_html = f"""
<div style="
    background:#f5f5f5;
    border-radius:12px;
    overflow:hidden;
    font-family:Georgia, serif;
    border:1px solid #dddddd;
">

    <div style="
        background:#2f3b52;
        color:white;
        padding:18px 24px;
    ">
        <h2 style="
            margin:0;
            font-size:24px;
        ">
            Valve Publisher Profile
        </h2>


        <p style="
            margin:6px 0 0;
            opacity:0.85;
            font-size:14px;
        ">
            Steam Dataset Summary
        </p>
    </div>


    <table style="
        width:100%;
        border-collapse:collapse;
        font-size:15px;
    ">
        <tr style="background:#eeeeee;">
            <td style="
                padding:12px 20px;
                width:45%;
            ">
                <b>Number of games</b>
            </td>

            <td style="padding:12px 20px;">
                {game_count}
            </td>
        </tr>

        <tr>
            <td style="padding:12px 20px;">
                <b>Average price</b>
            </td>

            <td style="padding:12px 20px;">
                ${mean_price:.2f}
            </td>
        </tr>

        <tr style="background:#eeeeee;">
            <td style="padding:12px 20px;">
                <b>Median price</b>
            </td>

            <td style="padding:12px 20px;">
                ${median_price:.2f}
            </td>
        </tr>

        <tr>
            <td style="padding:12px 20px;">
                <b>Dominant genre</b>
            </td>

            <td style="padding:12px 20px;">
                {dominant_genre}
                ({dominant_count} games)
            </td>
        </tr>
    </table>


    <div style="
        margin:20px 24px;
        padding:16px 18px;
        background:#e8f5e9;
        border-left:5px solid #2e7d32;
        border-radius:8px;
    ">
        <div style="
            font-size:13px;
            text-transform:uppercase;
            letter-spacing:0.5px;
            color:#2e7d32;
            margin-bottom:6px;
        ">
            Featured Game
        </div>

        <div style="
            font-size:20px;
            font-weight:bold;
            margin-bottom:4px;
        ">
            {featured["name"]}
        </div>

        <div>
            {featured["positive_pct"]:.2f}% positive ratings
            across {int(featured["total_ratings"]):,} ratings
        </div>
    </div>


    <div style="
        padding:0 24px 22px;
    ">
        <h3 style="
            margin-bottom:8px;
            color:#2f3b52;
        ">
            Publisher Profile
        </h3>

        <p style="
            margin:0;
            line-height:1.65;
            font-size:15px;
        ">
            {publisher_profile}
        </p>
    </div>


    <div style="
        background:#eeeeee;
        color:#777777;
        padding:10px 24px;
        font-size:12px;
        font-style:italic;
        text-align:right;
    ">
        Source: Steam Store Games dataset
    </div>

</div>
"""

display(
    HTML(card_html)
)
